    {
      "card_ids": ["C12"],
      "claim": "In NHPs, the close LRRK2 inhibitor analog GNE-7915 achieved terminal B_u/P_u and CSF/P_u AUC ratios of 0.6 and 0.8, indicating high brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "GNE-7915 is brain-penetrant, with a CSF/plasma unbound ratio of 0.6 in rats after intravenous dosing.",
