    {
      "card_ids": ["C06"],
      "claim": "In non-human primates, GNE-7915 showed a Cub/Cup ratio of 0.69, indicating good CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A morpholine-substituted pyrimidine radiotracer reached a whole-brain SUV of 2.8 within 5 minutes in rats, demonstrating that this heteroaromatic morpholine motif is brain penetrant.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "PF-06455943, a morpholine-containing heteroaromatic, showed favorable brain uptake in rodent autoradiography and PET imaging.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "CLR457, a morpholinopyrimidine with CF3/amino heteroaromatic features, had a brain/plasma AUC ratio of 0.07 and poor penetration, but its additional polar oxazolidinone-like motif limits transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query matches GNE-0877, a known brain-penetrant LRRK2 inhibitor; strong supportive evidence from the close analog GNE-7915 and other morpholine-containing CNS penetrants outweighs poor-penetration records from less transferable scaffolds, so meaningful CNS access is predicted.",
  "evidence_gaps": [
