    "No explicit P-gp/BCRP efflux data for the query are provided, though the close analog evidence suggests adequate net brain exposure."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C12"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "LRRK2 inhibitor CNS PK"
    }
  ],
  "revision_action": "initial"
}

